export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  return {
    scheme: m[1],
    authority: m[2],
    path: m[3],
    query: m[4],
    fragment: m[5],
  }
}

export function splitAuthority(a) {
  let userinfo
  let rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) {
    userinfo = a.slice(0, at)
    rest = a.slice(at + 1)
  }
  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  let host = rest
  let port
  if (colon >= 0) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function pct(s, name) {
  if (s === undefined) return s
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new UriError(`the ${name} has a truncated percent-encoding`)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

export function removeDots(path) {
  let input = path
  let out = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(c) {
  const scheme = c.scheme === undefined ? undefined : lower(c.scheme)
  const path = pct(c.path, 'path')
  let userinfo, host, port
  const hasAuth = c.authority !== undefined
  if (hasAuth) {
    const p = splitAuthority(c.authority)
    userinfo = pct(p.userinfo, 'userinfo')
    host = lower(pct(p.host, 'host'))
    port = p.port
  }
  const query = pct(c.query, 'query')
  const fragment = pct(c.fragment, 'fragment')
  if (port !== undefined && (port === '' || (scheme !== undefined && DEFAULT_PORTS[scheme] === port))) port = undefined
  let np = removeDots(path)
  if (hasAuth && np === '') np = '/'
  let r = ''
  if (scheme !== undefined) r += scheme + ':'
  if (hasAuth) {
    r += '//'
    if (userinfo !== undefined) r += userinfo + '@'
    r += host
    if (port !== undefined) r += ':' + port
  }
  r += np
  if (query !== undefined) r += '?' + query
  if (fragment !== undefined) r += '#' + fragment
  return r
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      let p = ref.path
      if (!p.startsWith('/')) {
        if (base.authority !== undefined && base.path === '') p = '/' + p
        else {
          const i = base.path.lastIndexOf('/')
          p = (i >= 0 ? base.path.slice(0, i + 1) : '') + p
        }
      }
      t.path = removeDots(p)
    }
  }
  return t
}
